// Package openapi carries what the node serves, in the form a machine reads.
//
// The document is generated by cmd/openapi from server/reach's table, the
// routing source, and the handlers' own doc comments — never written by hand.
// It lives here rather than in docs/ because Go embeds a file only from its
// own directory downward, and the thing that serves it should hold it.
package openapi

import _ "embed"

//go:embed openapi.json
var document []byte

// Document is the OpenAPI document for this build.
func Document() []byte { return document }
